const paths={bag:'M6 7h12l2 14H4L6 7Zm3 0V5a3 3 0 0 1 6 0v2',search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m8 10 4 4 4-4',user:'M20 21v-2a8 8 0 0 0-16 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L19 6',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Zm-4 10 3 3 5-6',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.6l6.2-.9L12 3Z',truck:'M1 5h13v12H1zM14 9h4l4 4v4h-8M7 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm13 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',store:'M3 10v11h18V10M2 10l2-7h16l2 7M2 10c1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 5 0M9 21v-7h6v7',home:'m2 11 10-9 10 9M5 9v13h14V9M9 22v-8h6v8',shirt:'m8 3-6 4 3 5 3-2v12h8V10l3 2 3-5-6-4c0 4-8 4-8 0Z',beauty:'M8 10h8v12H8zM9 10V5l6-3v8M7 15h10',tech:'M3 4h18v13H3zM8 22h8M12 17v5',sport:'m4 6 14 14M2 8l6-6M16 22l6-6M1 5l4-4M19 23l4-4',leaf:'M20 3C9 0 2 8 5 16s18 3 15-13ZM3 22 16 8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.bag}"/></svg>`;
const photo=(id,w=650)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const stores=[{name:'Casa Aurora',city:'Cianorte',type:'Oficial',initial:'ca',desc:'Casa, decoração & boas ideias'},{name:'Essencial Concept',city:'Maringá',type:'Indicada',initial:'e.',desc:'Seu estilo, todos os dias'},{name:'Verde & Vida',city:'Cianorte',type:'',initial:'vv',desc:'Mais natureza na sua rotina'}];
for(const s of EXTRA_DEMO_STORES)stores[s.id]={name:s.name,city:s.city,type:'',initial:s.initial,desc:s.desc};
const products=marketplaceCatalog(photo);
const categories=[['Casa & decoração','home'],['Moda & acessórios','shirt'],['Beleza & cuidados','beauty'],['Eletrônicos','tech'],['Esporte & lazer','sport'],['Jardim & plantas','leaf'],['Livros & digitais','grid']];
stores.forEach((s,i)=>{const c=readMarketplace().stores.find(x=>x.id===i);if(c){s.name=c.name;s.city=c.city;s.type=c.seal==='official'?'Oficial':c.seal==='indicated'?'Indicada':'';}});
const state={city:readDeliveryLocation()?.city||'Escolha sua cidade',category:'',query:'',store:null,favorites:new Set(),cart:new Map(),view:'all',status:'ready'};
const money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<a class="brand" href="#" aria-label="Tem Logo Ali — início"><span class="brand-mark">${icon('bag')}</span><span class="brand-name">tem logo<span>ali.</span></span></a>`;
const badge=s=>{const configured=readMarketplace().stores.find(x=>x.id===stores.indexOf(s)),type=configured?.seal||(s.type==='Oficial'?'official':s.type==='Indicada'?'indicated':'none');return type!=='none'?'<button class="badge final-seal" data-action="badge" data-type="'+(type==='official'?'Oficial':'Indicada')+'">'+sealSVG(type)+'</button>':''};
function card(p){if(!productVisibleForPostal(p))return "";const s=stores[p.store];return `<article class="product"><button class="product-photo" data-action="product" data-id="${p.id}" aria-label="Ver ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy" width="650" height="650"></button><button class="favorite" data-action="favorite" data-id="${p.id}" aria-pressed="${state.favorites.has(p.id)}" aria-label="Favoritar ${p.name}">${icon('heart')}</button><div class="product-info"><div class="seller-line">${icon(s.type==='Oficial'?'shield':s.type==='Indicada'?'star':'store')} ${escape(s.name)} <span>· ${escape(s.city)}</span></div><button class="product-title" data-action="product" data-id="${p.id}">${p.name}</button><div class="product-meta">${p.description}</div><div class="product-bottom"><div><div class="price">${money(p.price)}</div><div class="price-note">${p.type==='virtual'?'Download digital · sem frete':'Consulte entrega ou retirada'}</div></div><button class="add" data-action="add" data-id="${p.id}" aria-label="Adicionar ${p.name} à sacola">${icon('plus')}</button></div></div></article>`}
function render(){products.splice(0,products.length,...marketplaceCatalog(photo));state.city=readDeliveryLocation()?.city||'Escolha sua cidade';const positions=[...document.querySelectorAll('.carousel-track')].map(t=>[t.id,t.scrollLeft]);document.querySelectorAll('.carousel-track').forEach(t=>t._cleanup?.());document.querySelector('#app').innerHTML=`
<div class="utility"><div class="wrap"><span>${icon('pin')} Cianorte, Maringá e região. O comércio local mais perto de você.</span><span class="demo-text">PRÉVIA VISUAL · DADOS FICTÍCIOS</span></div></div>
<div class="wrap seller-entry"><span>Seu comércio também tem lugar aqui.</span><a href="./vender.html">Quero vender</a><a href="./painel.html#seller">Central de Vendedores →</a></div><header class="header"><div class="wrap header-main">${brand()}<button class="location-btn" data-action="location">${icon('pin')}<span><small>Você está em</small><b>${escape(state.city)}${readDeliveryLocation()?' · '+escape(readDeliveryLocation().cep):''}</b></span>${icon('chevron','chev')}</button><form class="search" role="search"><input name="q" type="search" aria-label="Buscar produtos ou lojas" placeholder="O que você está procurando hoje?" value="${escape(state.query)}"><button aria-label="Buscar">${icon('search')}</button></form><button class="header-action account" data-action="account">${icon('user')}<span class="label">Minha conta</span></button><button class="header-action" data-action="cart" aria-label="Abrir sacola"><span class="bag-wrap">${icon('bag')}<span class="count">${[...state.cart.values()].reduce((a,b)=>a+b,0)}</span></span><span class="label">Sacola</span></button></div><nav class="nav" aria-label="Categorias"><div class="wrap"><a class="all" href="#categorias">${icon('menu')} Todas as categorias</a>${categories.slice(0,4).map(([c])=>`<button data-action="category" data-category="${c}" class="${state.category===c?'active':''}">${c}</button>`).join('')}<a class="local-link" href="#lojas">${icon('store')} Lojas da região</a></div></nav></header>
<main id="conteudo" class="wrap"><button class="breadcrumb" data-action="location" style="border:0;background:none;padding:0">${icon('pin')} Descubra o comércio de <b>${state.city} e região</b>${icon('chevron')}</button>
${!products.some(p=>productVisibleForPostal(p))?`<aside class="coverage-notice"><h2>${readDeliveryLocation()?'Ainda não há ofertas para este CEP':'Vamos encontrar as lojas da sua região?'}</h2><p>Confirme sua cidade e CEP para ver produtos com entrega ou retirada disponíveis.</p><button class="btn secondary" data-action="location">Escolher cidade e CEP</button></aside>`:''}<section class="hero" aria-label="Compre no comércio local"><div class="hero-copy"><div class="eyebrow"><i></i> GRANDES DESCOBERTAS, BEM AQUI.</div><h1>Encontre perto.<br>Compre <em>local.</em></h1><p>Suas lojas favoritas e novas descobertas.<br>Tudo em um só lugar, pertinho de você.</p><a class="btn" href="#produtos">Explorar produtos ${icon('arrow')}</a></div><div class="hero-photo"><img src="${photo('photo-1616486338812-3dadae4b4ace',1000)}" alt="Ambiente acolhedor com móveis e decoração em tons naturais" fetchpriority="high"><div class="hero-note">${icon('store')}<div><b>Da sua região, para você.</b><small>Conheça quem faz o comércio local.</small></div></div></div></section>
<div class="benefits"><div class="benefit">${icon('store')}<div><b>Valorize quem está perto</b><small>Compre de empresas da sua região</small></div></div><div class="benefit">${icon('bag')}<div><b>Várias lojas, uma só sacola</b><small>Encontre tudo no mesmo lugar</small></div></div><div class="benefit">${icon('truck')}<div><b>Receba ou retire na loja</b><small>Consulte as opções de cada loja</small></div></div></div>
<section class="section" id="categorias"><div class="section-head"><h2>O que combina com seu dia?</h2><button class="text-link" data-action="clear">Ver tudo ${icon('arrow')}</button></div><div class="categories">${categories.map(([c,i])=>`<button class="category ${state.category===c?'selected':''}" data-action="category" data-category="${c}"><span class="category-icon">${icon(i)}</span><b>${c}</b></button>`).join('')}</div></section>
<section class="section" id="produtos"><div class="section-head"><div><h2 id="product-heading">Descobertas para você</h2><p id="product-subheading">Uma seleção de produtos do comércio da região.</p></div><button class="text-link" data-action="clear">Ver todos ${icon('arrow')}</button></div><div id="filter-note"></div><div class="products" id="product-grid" aria-live="polite"></div></section>
<section class="section" id="lojas"><div class="section-head"><div><h2>Gente daqui. Lojas para conhecer.</h2><p>Lojas para retirada na cidade do seu CEP, sem limite de distância.</p></div><button class="text-link" data-action="seals">Entenda os selos ${icon('arrow')}</button></div><div class="store-grid">${stores.map((s,i)=>{const configured=readMarketplace().stores.find(x=>x.id===i),cep=localStorage.getItem('temlogoali.buyer-cep');if(!storeVisibleForPostal(i))return '';return `<article class="store-card"><div class="store-top"><div class="store-logo">${s.initial}</div><div><h3>${escape(s.name)}</h3><small>${escape(s.city)} · ${s.desc}</small></div></div><div class="store-bottom">${badge(s)}<button class="text-link" data-action="store" data-id="${i}">Explorar loja ${icon('arrow')}</button></div></article>`}).join('')}</div></section>
<section class="bottom-banner"><div><h2>Uma cidade cheia de possibilidades.</h2><p>Descubra produtos, conheça lojas e faça parte do comércio da sua região.</p></div><button class="btn" data-action="location">Explorar minha região ${icon('arrow')}</button></section></main>
<footer class="footer"><div class="wrap"><div class="footer-main">${brand()}<p>Cianorte, Maringá e região.<br>Conectando você ao comércio local.</p><button class="text-link" data-action="about">Sobre esta prévia ${icon('arrow')}</button></div><div class="footer-bottom"><span>Marketplace Local · Nome e identidade provisórios.</span><span>Produtos e lojas fictícios. Nenhuma compra real é realizada.</span></div></div></footer><div class="state-links"><a href="./painel.html#admin">Administração · demonstração</a><button data-action="design">Base visual</button><button data-action="loading">Demonstrar carregamento</button><button data-action="empty">Demonstrar catálogo vazio</button></div>
<nav class="mobile-nav" aria-label="Navegação principal"><a class="active" href="#">${icon('home')}Início</a><a href="#categorias">${icon('grid')}Categorias</a><button data-action="favorites">${icon('heart')}Favoritos</button><button data-action="account">${icon('user')}Conta</button></nav>`;renderProducts();mountMerchandising({products,categories,icon,card,state,render});positions.forEach(([id,left])=>{const t=document.getElementById(id);if(t)t.scrollLeft=left;});discovery.render();updateBuyerHeader();}
function renderProducts(){const grid=document.querySelector('#product-grid');grid.setAttribute('aria-busy',state.status==='loading');if(state.status==='loading'){grid.innerHTML=`<p class="loading-caption" role="status">Buscando descobertas da região…</p>${Array.from({length:4},()=>'<div class="skeleton" aria-hidden="true"></div>').join('')}`;return}const q=state.query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();let list=products.filter(p=>productVisibleForPostal(p)&&(!state.category||p.category===state.category)&&(state.store===null||p.store===state.store)&&(state.view!=='favorites'||state.favorites.has(p.id))&&`${p.name} ${stores[p.store].name} ${p.category}`.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q));if(state.status==='empty')list=[];const filtered=state.query||state.category||state.store!==null||state.view==='favorites';document.querySelector('#product-heading').textContent=state.view==='favorites'?'Seus favoritos':state.store!==null?`Produtos de ${stores[state.store].name}`:state.category||'Descobertas para você';document.querySelector('#product-subheading').textContent=filtered?`${list.length} produto${list.length===1?'':'s'} encontrado${list.length===1?'':'s'}.`:'Uma seleção de produtos do comércio da região.';document.querySelector('#filter-note').innerHTML=filtered?`<div class="filter-note">${state.query?`Busca: “${escape(state.query)}”`:'Seleção personalizada'}<button class="text-link" data-action="clear">Limpar filtros ×</button></div>`:'';grid.innerHTML=list.length?list.map(card).join(''):`<div class="empty">${icon('search')}<h3>${state.status==='empty'?'Novas lojas estão a caminho':'Nenhum produto por aqui ainda'}</h3><p>${state.status==='empty'?`Não há produtos disponíveis nesta demonstração da região de ${state.city}.`:'Confirme sua cidade e CEP para consultar os produtos atendidos na sua região.'}</p><button class="btn" data-action="clear">${state.status==='empty'?'Voltar ao catálogo demonstrativo':'Explorar todos os produtos'}</button></div>`;}
let toastTimer;function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2800)}
const dialog=document.querySelector('#modal');function modal(title,body,mode=''){dialog.classList.toggle('cart-drawer',mode==='cart');dialog.innerHTML=`<div class="dialog-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${body}`;if(!dialog.open)dialog.showModal()}
function cart(){modal('Sua sacola',state.cart.size?`${[...state.cart].map(([id,qty])=>{const p=products[id];return `<div class="cart-item"><img src="${p.image}" alt=""><div>${p.name}<small>${stores[p.store].name} · ${money(p.price)} × ${qty}</small></div><button data-action="remove" data-id="${id}" aria-label="Remover uma unidade de ${p.name}">−</button><b>${qty}</b><button data-action="add" data-id="${id}" aria-label="Adicionar uma unidade de ${p.name}">+</button></div>`}).join('')}<div class="dialog-row"><b>Subtotal dos produtos</b><strong class="price">${money([...state.cart].reduce((sum,[id,qty])=>sum+products[id].price*qty,0))}</strong></div><p class="dialog-copy">Sacola demonstrativa. Frete e checkout serão detalhados na próxima etapa. Nenhuma cobrança é realizada.</p>`:`<div class="empty">${icon('bag')}<h3>Sua sacola está esperando</h3><p>Explore os produtos e adicione seus favoritos.</p><button class="btn" data-action="close">Continuar explorando</button></div>`)}
function clear(){state.category='';state.query='';state.store=null;state.view='all';state.status='ready';render();}
document.addEventListener('submit',e=>{if(!e.target.matches('.search'))return;e.preventDefault();state.query=new FormData(e.target).get('q').trim();state.store=null;state.status='ready';renderProducts();document.querySelector('#produtos').scrollIntoView()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(a==='close'){dialog.close();return}if(a==='location'){modal('Qual é a sua região?',`<p class="dialog-copy">Escolha uma região para explorar. A entrega de cada loja será confirmada pelo endereço no checkout.</p>${['Cianorte','Maringá'].map(c=>`<button class="choice" data-action="city" data-city="${c}">${icon('pin')}<span><b>${c} e região</b><small>Paraná · ${state.city===c?'Região selecionada':'Explorar esta região'}</small></span></button>`).join('')}<p class="dialog-copy" style="margin-top:18px">Catálogo compartilhado de demonstração. Não representa cobertura real.</p>`)}else if(a==='city'){state.city=b.dataset.city;dialog.close();render();toast(`Região alterada para ${state.city}. Cobertura depende do endereço.`)}else if(a==='category'){state.category=b.dataset.category;state.query='';state.store=null;state.view='all';state.status='ready';render();document.querySelector('#produtos').scrollIntoView()}else if(a==='clear'){clear();document.querySelector('#produtos').scrollIntoView()}else if(a==='store'){state.store=id;state.category='';state.query='';state.view='all';state.status='ready';render();document.querySelector('#produtos').scrollIntoView()}else if(a==='favorite'){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);document.querySelectorAll('.favorite').forEach(b=>b.setAttribute('aria-pressed',String(state.favorites.has(Number(b.dataset.id)))));if(state.view==='favorites')renderProducts();toast(state.favorites.has(id)?'Produto salvo nos favoritos desta sessão.':'Produto removido dos favoritos.')}else if(a==='favorites'){state.view='favorites';state.category='';state.query='';state.store=null;state.status='ready';render();document.querySelector('#produtos').scrollIntoView()}else if(a==='add'){state.cart.set(id,(state.cart.get(id)||0)+1);const wasCart=dialog.open&&dialog.querySelector('#modal-title').textContent==='Sua sacola';render();if(wasCart)cart();toast('Produto adicionado à sacola demonstrativa.')}else if(a==='remove'){const qty=state.cart.get(id);qty>1?state.cart.set(id,qty-1):state.cart.delete(id);render();cart()}else if(a==='cart')cart();else if(a==='product'){const p=products[id],s=stores[p.store];modal(p.name,`<img class="dialog-photo" src="${p.image}" alt="${p.name}"><div class="dialog-row"><span class="dialog-copy">${escape(s.name)} · ${escape(s.city)}</span>${badge(s)}</div><p class="dialog-copy">${p.description}. Produto ilustrativo para apresentar a experiência do marketplace.</p><div class="dialog-row"><strong class="price">${money(p.price)}</strong><button class="btn" data-action="add" data-id="${id}">Adicionar à sacola ${icon('plus')}</button></div><p class="dialog-copy">Entrega ou retirada conforme a loja. Frete e cobertura dependem do endereço. A página completa de produto será criada na próxima etapa.</p>`)}else if(a==='badge'||a==='seals'){modal(a==='badge'?`Loja ${b.dataset.type}`:'Conheça os selos',`<p class="dialog-copy"><b>Loja Indicada</b><br>Conquista o selo com 100 pedidos realizados em um dia. Mantém o selo com média diária de 100 nos últimos 6 meses.<br><br><b>Loja Oficial</b><br>Possui Registro de Marca, cartão CNPJ e Contrato social aprovados. Não exige volume mínimo de vendas.<br><br>Pedidos realizados contam, mesmo sem pagamento confirmado. Os selos não representam garantia de entrega ou menor preço.</p><p class="dialog-copy" style="margin-top:18px">Nesta prévia, lojas e selos são fictícios. A Indicada passa por revisão semestral. O desenho dos selos é definitivo; as concessões das lojas desta demonstração são fictícias.</p>`)}else if(a==='account'){modal('Sua conta, tudo em um lugar',`<p class="dialog-copy">Aqui você poderá acompanhar pedidos, gerenciar endereços e conversar com a loja após uma compra.</p><div class="choice">${icon('user')}<span><b>Área do comprador</b><small>Será desenvolvida nas próximas telas.</small></span></div><p class="dialog-copy" style="margin-top:18px">Esta etapa apresenta a página inicial. Nenhum cadastro ou login real é realizado.</p><a class="btn secondary" style="margin-top:18px" href="./painel.html#seller">Sou lojista — acessar a central →</a>`)}else if(a==='about'){modal('Uma prévia do comércio local',`<p class="dialog-copy">Página inicial e base visual do Marketplace Local para Cianorte, Maringá e região.<br><br>Nome, fotos, produtos, lojas e preços são demonstrativos. Não há pagamentos, consultas de estoque ou cálculo logístico reais.<br><br>A navegação permite explorar categorias, buscar produtos, conhecer selos, guardar favoritos e experimentar a sacola.</p>`)}else if(a==='design'){modal('Base visual do marketplace',`<p class="dialog-copy">Uma identidade acolhedora, com hierarquia clara e espaço para os produtos.</p><div class="swatches"><div class="swatch" style="background:#164d3e;color:white">Verde · #164D3E</div><div class="swatch" style="background:#ddecbd">Sálvia · #DDECBD</div><div class="swatch" style="background:#f8f9f5;border:1px solid #e4e8e1">Claro · #F8F9F5</div></div><h3 style="margin:20px 0 8px">Manrope para títulos</h3><p class="dialog-copy">DM Sans para leitura, controles e informações.</p><div class="dialog-row"><button class="btn" data-action="close">Ação principal ${icon('arrow')}</button><button class="btn secondary" data-action="close">Secundária</button></div><div class="dialog-row">${badge(stores[0])}${badge(stores[1])}</div><p class="dialog-copy">Carrosséis com cinco produtos visíveis no desktop e dois no celular. Catálogo demonstrativo: 28 produtos. Componentes com foco visível e rótulos acessíveis.</p>`)}else if(a==='loading'){state.status='loading';renderProducts();document.querySelector('#produtos').scrollIntoView();setTimeout(()=>{if(state.status==='loading'){state.status='ready';renderProducts()}},1500)}else if(a==='empty'){state.status='empty';renderProducts();document.querySelector('#produtos').scrollIntoView()}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG')e.target.parentElement.classList.add('image-failed')},true);
document.addEventListener('click',e=>{if(e.target.closest('.brand')||e.target.closest('.mobile-nav a.active')){e.preventDefault();clear();window.scrollTo({top:0,behavior:'smooth'})}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const discovery=createDiscovery({products,stores,categories,state,card,badge,icon,money,escape,render,modal,toast});
render();

document.addEventListener('click',e=>{if(!e.target.closest('[data-action="location"]'))return;e.preventDefault();e.stopImmediatePropagation();showLocationChooser(modal);},true);
window.addEventListener('delivery-location-change',()=>render());
window.addEventListener('storage',e=>{if(['temlogoali.settings.v1','temlogoali.location.v1','marketplace.product-drafts.v1'].includes(e.key))render()});
if(!readDeliveryLocation())showLocationChooser(modal);

dialog.addEventListener('click',e=>{if(e.target!==dialog||!dialog.classList.contains('cart-drawer'))return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});

